<?php require '_layout.php';$db=db();
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$id=(int)($d['id']??0);
 if(isset($d['del'])&&$id)$db->prepare('DELETE FROM banners WHERE id=?')->execute([$id]);
 elseif(trim($d['title'])!==''){$v=[trim($d['title']),trim($d['subtitle']),safe_link($d['link']??''),trim($d['btn']),(int)$d['color']%3,(int)$d['sort'],isset($d['active'])?1:0];
  if($id)$db->prepare('UPDATE banners SET title=?,subtitle=?,link=?,btn=?,color=?,sort=?,active=? WHERE id=?')->execute(array_merge($v,[$id]));else $db->prepare('INSERT INTO banners(title,subtitle,link,btn,color,sort,active) VALUES(?,?,?,?,?,?,?)')->execute($v);}
 header('Location: banners.php?ok=1');exit;}
ahead('Homepage banners','banners.php');?><?=isset($_GET['ok'])?'<p class="okm">Saved</p>':''?><p>Offer cards shown under the homepage hero. Link to any page, for example <code>shop.php?cat=beauty-hair</code>.</p>
<?php foreach(array_merge($db->query('SELECT * FROM banners ORDER BY sort,id')->fetchAll(),[['id'=>0,'title'=>'','subtitle'=>'','link'=>'shop.php','btn'=>'Shop now','color'=>0,'sort'=>0,'active'=>1]]) as $z): ?>
<form method="post" class="zr"><?=csrf()?><input type="hidden" name="id" value="<?=$z['id']?>"><input name="title" placeholder="<?=$z['id']?'':'New banner title'?>" value="<?=e($z['title'])?>"><input name="subtitle" placeholder="Subtitle" value="<?=e($z['subtitle'])?>"><input name="link" placeholder="Link" value="<?=e($z['link'])?>"><input name="btn" placeholder="Button text" value="<?=e($z['btn'])?>"><select name="color"><?php foreach(['Purple','Green','Gold'] as $i=>$c)echo '<option value="'.$i.'" '.($z['color']==$i?'selected':'').'>'.$c.'</option>'; ?></select><input name="sort" type="number" style="max-width:70px" value="<?=e($z['sort'])?>" title="Order"><label><input type="checkbox" name="active" <?=$z['active']?'checked':''?>> Live</label><button class="btn"><?=$z['id']?'Save':'Add banner'?></button><?php if($z['id']): ?><button class="btn ghost" name="del" value="1" onclick="return confirm('Delete?')">Delete</button><?php endif; ?></form><?php endforeach; afoot();
